      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications and standards govern your process?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS adheres to NIST SP 800-88 Rev. 2 media sanitization standards, ISO environmental frameworks, and DoD 5220.22-M guidelines. We deliver full chain of custody documentation and Certificates of Destruction to satisfy state and federal compliance audits."
          }
        },
        {
          "@type": "Question",
          "name": "What geographical areas do you service in Kern County?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We provide scheduled pickups throughout Bakersfield, Oildale, Rosedale, Stockdale, and neighboring communities. Our service footprint encompasses corporate offices, medical centers, packaging facilities, and logistics parks across the southern San Joaquin Valley."
          }
        },
        {
          "@type": "Question",
          "name": "Is electronic recycling pickup free for commercial clients?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, pickup is typically complimentary for qualifying volumes of commercial IT hardware, computers, laptops, and networking assets. Contact our team to review your inventory and confirm eligibility for scheduled logistics."
          }
        },
        {
          "@type": "Question",
          "name": "How do you ensure data security during transit?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Assets are secured in locked transport containers with serialized tamper-evident seals before leaving your facility. Every shipment maintains documented custody transfer from initial collection through secure processing."
          }
        },
        {
          "@type": "Question",
          "name": "Can STS handle large-scale enterprise liquidations?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Our 200,000 sq ft processing operation accommodates large data center decommissioning projects, multi-building enterprise refreshes, and ongoing corporate IT replacement cycles across all 50 states."
          }
        },
        {
          "@type": "Question",
          "name": "How does California universal waste law affect my business?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "California DTSC regulations prohibit landfill disposal of electronic devices, classifying them as universal waste. Working with STS ensures proper regulatory tracking and eliminates organizational liability for hazardous electronic components."
          }
        },
        {
          "@type": "Question",
          "name": "How quickly can pickup be scheduled in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Commercial pickups across Bakersfield and Kern County are typically scheduled within three to five business days of inventory confirmation, with expedited logistics available for time-sensitive corporate decommission projects."
          }
        },
        {
          "@type": "Question",
          "name": "Where is equipment collected in Bakersfield processed?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment collected in Bakersfield is staged locally and transported to one of our two certified processing facilities in Jacksonville, Texas and Houston, Texas, where all data destruction and material recovery takes place."
          }
        }
